def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    fg = Counter(x for row in grid for x in row if x != bg).most_common(1)[0][0]

    active_rows = [r for r in range(h) if any(grid[r][c] == fg for c in range(w))]
    groups = []
    for r in active_rows:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)

    out = [row[:] for row in grid]
    if len(groups) >= 2:
        upper, lower = groups[0], groups[-1]
        for i, r in enumerate(lower):
            if i < len(upper):
                ur = upper[i]
                for c in range(w):
                    if grid[ur][c] == fg and grid[r][c] == bg:
                        out[r][c] = 1
    return out
